import json

def add(a, b):
    return a + b

def multiply(a, b):
    return a * b

TOOLS = {"add": add, "multiply": multiply}

def run_tool(call_json):
    call = json.loads(call_json)
    return TOOLS[call["tool"]](**call["args"])

def fake_llm(history):
    if len(history) == 0:
        return {"type": "tool", "call": json.dumps({"tool": "multiply", "args": {"a": 3, "b": 4}})}
    if len(history) == 1:
        return {"type": "tool", "call": json.dumps({"tool": "add", "args": {"a": history[-1], "b": 2}})}
    return {"type": "final", "answer": f"The total is {history[-1]}"}

history = []
steps = 0
while True:
    action = fake_llm(history)
    steps += 1
    if action["type"] == "final":
        print(action["answer"])
        break
    history.append(run_tool(action["call"]))
